-- Wächter Migration 208 (nur lesen). Erwartungen: werkzeuge/m208_md5.json. funktionen = die von 208 geänderten und neuen Funktionen.
SELECT (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['talents_ki_einstellungen_aktion', 'briefing_periode', 'briefing_zeitplan_text', 'briefing_darf', 'briefing_talents_fuer', 'briefing_talents_waise', 'briefing_manager', 'briefing_empfaenger_alle', 'briefing_empfaenger', 'briefing_naechster', 'briefing_sichtbar', 'briefing_bausteine_fuer', 'briefing_ergebnis_lesbar', 'briefing_kopf', 'briefing_standard_anlegen', 'briefing_bs_termine', 'briefing_bs_kunden_mails', 'briefing_bs_geschaeft_mails', 'briefing_bs_talents_zahlen', 'briefing_bs_talents_ki', 'briefing_bs_talents_ki_fertig', 'briefing_bs_talents_aufgaben', 'briefing_mail_standard', 'briefing_mail_platzhalter', 'briefing_mail_normal', 'briefing_html_text', 'briefing_absender', 'briefing_mail_bauen', 'briefing_faellig', 'briefing_ergebnis_bauen', 'briefing_abschluss', 'briefing_web', 'briefing_ui_aktion', 'briefing_meldung', 'briefing_kachel', 'briefing_talent_ui', 'briefing_start_stand', 'briefing_chat'])) AS funktionen;
